/**
 * Omni Sweep (2026-11-03): Ultimate Equipment Guide Volume 1 (Mongoose
 * Publishing, 2002) — every purchasable entry in the book parsed into
 * crunch. The book is overwhelmingly mundane/alchemical equipment;
 * its only entries built like magic items are the psychic tattoos of
 * the Psychic Mastery chapter, which carry printed Market Prices and
 * are created with the Inscribe Psychic Tattoo item-creation feat, so
 * they are filed as wondrous-slotless magic items. Everything else —
 * including the sacred oils, which the book prices per vial in a plain
 * table with no caster level — is equipment. Names and costs are as
 * printed (chapter text wins over the Rules Summary where they
 * differ); notes are mechanical facts in our own words. Entries whose
 * names already exist in the catalog were skipped per the sweep
 * dedupe rule and are listed in the sweep report.
 */
